# Do it cleanly: after match end, take next 30 newline-separated token-groups
def try_block(txt,m):
    s=txt[m.end():].split('\n')[:30]
    rows=[]
    for r_ in s:
        # remove leading/trailing quote artifacts
        cand=re.sub(r'\{"[^}]*', '', r_)
        cand=cand.strip('"').strip(' ')
        tokens=[x for x in cand.split() if x.isdigit()]
        if len(tokens)==30 and all(len(x)==1 for x in [cand]):
            rows.append([int(x) for x in cand.split()])
        elif len(cand.split())>=30 and all(x.isdigit() for x in cand.split()):
            rows.append([int(x) for x in cand.split()])
        else:
            return None
    if len(rows)<30: return None
    g=[[int(x) for x in r_] for r_ in rows]
    return g
