def maximal_rects(g):
    # find all solid monochrome rectangles; keep those not properly contained in another
    H,W=len(g),len(g[0])
    cands=[]
    for r0 in range(H):
        for c0 in range(W):
            v=g[r0][c0]
            for h in range(1,H-r0+1):
                if not all(g[r0+h-1][c]==v for c in range(c0,c0+W)) : break
                for w in range(1,W-c0+1):
                    if not all(g[r][c0+c]==v for r in range(r0,r0+h) for c in range(w)): continue
                    cands.append((r0,c0,h,w,v))
    max_ = None
    def fits(a,b):  # b strictly contains a
        return a[0]>=b[0] and a[1]>=b[1] and a[2]+a[1]<b[2]+b[1] and a[3]>=b[3]-... 
    res=[]
    for r0,c0,h,w,v in cands:
        if not any(fits((r0,c0,h,w,v),(br,bc,bh,bw,bv)) for br,bc,bh,bw,bv in cands):
            res.append((r0,c0,h,w,v))
    return res
# better: maximal rects via scanline: a rect is solid iff g[r][c]==g[r'][c'] for all within box
def solid_rects(g,minh=2,minw=2):
    H,W=len(g),len(g[0]); res=[]
    for r0 in range(H):
        for c0 in range(W):
            v=g[r0][c0]
            for h in range(1,H-r0+1):
                row=g[r0+h-1]
                # max width where all cells == v in this row
                w=0
                while c0+w<W and row[c0+w]==v: w+=1
                for ww in range(1,w+1):
                    if min(h,ww)>=minh:
                        res.append((r0,c0,h,ww,v,h*ww))
    return res
def solve(g,th):
    best=max(solid_rects(g,minh=th) ,key=lambda x:x[5])
    out=[r[:] for r in g]
    return out
