def rectmap(g):
    # maximal axis-aligned solid monochrome rects, by scanline (heights map) — collect candidates via rectangle per-cell expansion, keep maximal ones (not contained in larger same-color rect)
    H,W=len(g),len(g[0]); out=[]
    # For each color, compute for each cell the max height and width of solid run? Use approach: candidate rects = for each top-left, max extent where g==v; then prune contained.
    cands=[]
    for r0 in range(H):
        for c0 in range(W):
            v=g[r0][c0]
            h=0
            while r0+h<H and all(g[r0+h][c]==v for c in range(c0,W)): h+=1
            w=0
            while c0+w<W and all(g[r][c0]==v for r in range(r0,r0+h)) and True: pass
            # simpler: max width with column consistency within h rows
            ww=0
            while c0+ww<W and all(g[r][c0+ww]==v for r in range(r0,r0+h)): ww+=1
            if hh:=h: pass
            for hh in range(1,h+1):
                for ww2 in range(1,ww+1):
                    cands.append((r0,c0,hh,ww2,v,hh*ww2))
    # keep only maximal: no other rect strictly containing it with same color and area>=? containment: r bigger, c bigger, contains positionally
    res=[]
    for a in cands:
        if not any(b[0]<=a[0] and b[1]<=a[1] and b[0]+b[2]>a[0]+a[2] and b[1]+b[3]>a[1]+a[3] and b[4]==a[4] and (b[0],b[1])!=(a[0],a[1]) for b in cands):
            res.append(a)
    return res
